package android.content;import java.util.*;public class SharedPreferences{private final Map<String,Boolean> map=new HashMap<>();private final Map<String,String> texts=new HashMap<>();public String getString(String k,String d){return texts.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return map.getOrDefault(k,d);}public Editor edit(){return new Editor();}public class Editor{public Editor putString(String k,String v){texts.put(k,v);return this;}public Editor putBoolean(String k,boolean b){map.put(k,b);return this;}public void apply(){}public boolean commit(){return true;}}}